import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_ops_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

// Fused kernel: Mish + add_value + Hardtanh + scale
__global__ void fused_ops_kernel(const float* __restrict__ input,
                                 float* __restrict__ output,
                                 const float add_value,
                                 const float scale,
                                 const int size) {
    int idx = blockDim.x * blockIdx.x + threadIdx.x;
    if (idx < size) {
        float val = input[idx];
        // Mish
        float sp = logf(1.0f + expf(val));
        val = val * tanhf(sp);
        // Add
        val += add_value;
        // Hardtanh
        if (val < -1.0f) val = -1.0f;
        if (val >  1.0f) val =  1.0f;
        // Scale
        val *= scale;
        output[idx] = val;
    }
}

torch::Tensor fused_ops_cuda(torch::Tensor input, float add_value, float scale) {
    auto output = torch::zeros_like(input);
    int size = input.numel();

    const int block_size = 256;
    const int grid_size = (size + block_size - 1) / block_size;

    fused_ops_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        add_value,
        scale,
        size
    );

    return output;
}
""".strip()

fused_ops_cpp_source = (
    r"torch::Tensor fused_ops_cuda(torch::Tensor input, float add_value, float scale);"
)

fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_ops_cpp_source,
    cuda_sources=fused_ops_source,
    functions=["fused_ops_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Optimized Model using a custom fused CUDA kernel for Mish + add_value + Hardtanh + scale.
    """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, add_value, scale):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose2d(in_channels, out_channels, kernel_size, stride, padding, output_padding)
        self.add_value = add_value
        self.scale = scale
        self.fused_ops = fused_ops

    def forward(self, x):
        x = self.conv_transpose(x)
        x = self.fused_ops.fused_ops_cuda(x.contiguous(), self.add_value, self.scale)
        return x

